-- Sprint 19 additive migration. AtlasOS internal staff control plane only.
create table public.support_sessions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid references public.workspaces(id),requested_by uuid not null references auth.users(id),approved_by uuid references auth.users(id),reason text not null,status text not null default'pending' check(status in('pending','active','rejected','expired','ended')),read_only boolean not null default true,write_approval_status text not null default'not_requested' check(write_approval_status in('not_requested','pending','approved','rejected')),requested_at timestamptz not null default now(),approved_at timestamptz,expires_at timestamptz,ended_at timestamptz,duration_minutes integer not null check(duration_minutes between 15 and 240),version integer not null default 1);
create table public.feature_flags(id uuid primary key default gen_random_uuid(),key text unique not null,name text not null,description text not null,status text not null default'disabled' check(status in('enabled','disabled','beta')),rollout_percentage integer not null default 0 check(rollout_percentage between 0 and 100),created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1);
create table public.feature_flag_assignments(id uuid primary key default gen_random_uuid(),flag_id uuid not null references public.feature_flags(id),assignment_type text not null check(assignment_type in('country','region','organization','plan','percentage')),assignment_value text not null,enabled boolean not null default true,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1,unique(flag_id,assignment_type,assignment_value));
create table public.countries(id uuid primary key default gen_random_uuid(),code char(2)unique not null,name text not null,status text not null default'active',country_head_id uuid references auth.users(id),sales_director_id uuid references auth.users(id),support_director_id uuid references auth.users(id),operations_director_id uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1);
create table public.regions(id uuid primary key default gen_random_uuid(),country_id uuid not null references public.countries(id),code text not null,name text not null,status text not null default'active',regional_director_id uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1,unique(country_id,code));
insert into public.countries(code,name)select distinct country,case country when'US'then'United States'when'IN'then'India'when'AE'then'United Arab Emirates'else country end from organizations where country is not null on conflict(code)do nothing;
create table public.customer_health(id uuid primary key default gen_random_uuid(),organization_id uuid unique not null references public.organizations(id),score integer not null default 75 check(score between 0 and 100),churn_risk text not null default'low' check(churn_risk in('low','medium','high','critical')),renewal_at timestamptz,open_issues integer not null default 0,expansion_opportunity text,nps_score integer,ai_recommendation text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1);insert into public.customer_health(organization_id)select id from organizations on conflict(organization_id)do nothing;
create table public.customer_success_notes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),author_id uuid not null references auth.users(id),body text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1);
create table public.release_registry(id uuid primary key default gen_random_uuid(),version_name text not null,deployment_environment text not null check(deployment_environment in('staging','production')),status text not null default'pending_approval' check(status in('pending_approval','approved','published','rolled_back','archived')),notes text,approval_status text not null default'pending',approved_by uuid references auth.users(id),published_at timestamptz,rollback_reference uuid references public.release_registry(id),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1,unique(version_name,deployment_environment));
create table public.platform_metrics(id uuid primary key default gen_random_uuid(),metric text not null,value numeric(20,4)not null,unit text not null,dimensions jsonb not null default'{}',recorded_at timestamptz not null default now());
create table public.system_alerts(id uuid primary key default gen_random_uuid(),severity text not null check(severity in('info','warning','error','critical')),source text not null,title text not null,description text,status text not null default'open' check(status in('open','acknowledged','resolved')),acknowledged_by uuid references auth.users(id),resolved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1);
create index support_sessions_active_idx on public.support_sessions(requested_by,status,expires_at);create index feature_assignments_lookup_idx on public.feature_flag_assignments(assignment_type,assignment_value)where deleted_at is null;create index customer_health_risk_idx on public.customer_health(churn_risk,score)where deleted_at is null;create index metrics_recent_idx on public.platform_metrics(metric,recorded_at desc);create index alerts_status_idx on public.system_alerts(status,severity,created_at desc)where deleted_at is null;
alter table public.support_sessions enable row level security;alter table public.feature_flags enable row level security;alter table public.feature_flag_assignments enable row level security;alter table public.countries enable row level security;alter table public.regions enable row level security;alter table public.customer_health enable row level security;alter table public.customer_success_notes enable row level security;alter table public.release_registry enable row level security;alter table public.platform_metrics enable row level security;alter table public.system_alerts enable row level security;
create or replace function public.is_platform_staff()returns boolean language sql stable security definer set search_path=public as $$select coalesce(auth.jwt()->'app_metadata'->>'role','')in('super_admin','platform_support')$$;create or replace function public.is_super_admin()returns boolean language sql stable security definer set search_path=public as $$select coalesce(auth.jwt()->'app_metadata'->>'role','')='super_admin'$$;
create policy "support_staff_read" on public.support_sessions for select to authenticated using(public.is_platform_staff());create policy "flags_staff_read" on public.feature_flags for select to authenticated using(public.is_platform_staff());create policy "flag_assignments_staff_read" on public.feature_flag_assignments for select to authenticated using(public.is_platform_staff());create policy "countries_staff_read" on public.countries for select to authenticated using(public.is_platform_staff());create policy "regions_staff_read" on public.regions for select to authenticated using(public.is_platform_staff());create policy "customer_health_staff_read" on public.customer_health for select to authenticated using(public.is_platform_staff());create policy "customer_notes_staff_read" on public.customer_success_notes for select to authenticated using(public.is_platform_staff());create policy "releases_staff_read" on public.release_registry for select to authenticated using(public.is_platform_staff());create policy "metrics_staff_read" on public.platform_metrics for select to authenticated using(public.is_platform_staff());create policy "alerts_staff_read" on public.system_alerts for select to authenticated using(public.is_platform_staff());
create or replace function public.platform_customer_directory()returns table(organization_id uuid,organization_name text,status text,country text,region text,plan text,workspace_count bigint,users bigint,properties bigint,leads bigint,deals bigint,ai_usage numeric,mrr numeric,health_score integer,support_tickets integer,last_login timestamptz)language plpgsql security definer set search_path=public as $$begin if not is_platform_staff()then raise exception'platform staff required';end if;return query select o.id,o.name,o.status,o.country::text,null::text,coalesce(max(sp.name),'Starter'),count(distinct w.id),count(distinct om.user_id),count(distinct p.id),count(distinct l.id),count(distinct d.id),coalesce(sum(ou.quantity)filter(where ou.metric='ai_requests'),0),coalesce(max(sp.monthly_price),0),coalesce(max(ch.score),75),coalesce(max(ch.open_issues),0),null::timestamptz from organizations o left join workspaces w on w.organization_id=o.id left join organization_members om on om.organization_id=o.id and om.status='active'left join properties p on p.organization_id=o.id and p.deleted_at is null left join leads l on l.organization_id=o.id and l.deleted_at is null left join deals d on d.organization_id=o.id and d.deleted_at is null left join subscriptions s on s.organization_id=o.id and s.deleted_at is null left join subscription_plans sp on sp.id=s.plan_id left join organization_usage ou on ou.organization_id=o.id left join customer_health ch on ch.organization_id=o.id and ch.deleted_at is null group by o.id,o.name,o.status,o.country;end$$;
create or replace function public.platform_audit(p_event text,p_organization uuid,p_workspace uuid,p_message text)returns void language plpgsql security definer set search_path=public as $$begin insert into integration_logs(organization_id,workspace_id,provider_id,actor_id,level,event,message,audit_event)select p_organization,coalesce(p_workspace,(select id from workspaces where organization_id=p_organization order by created_at limit 1)),id,auth.uid(),'audit',p_event,p_message,true from integration_providers where code='supabase_storage'limit 1;end$$;
create or replace function public.request_support_session(p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;v_status text;begin if not is_platform_staff()then raise exception'platform staff required';end if;v_status=case when is_super_admin()then'active'else'pending'end;insert into support_sessions(organization_id,workspace_id,requested_by,approved_by,reason,status,approved_at,expires_at,duration_minutes)values((p_input->>'organizationId')::uuid,nullif(p_input->>'workspaceId','')::uuid,auth.uid(),case when is_super_admin()then auth.uid()else null end,p_input->>'reason',v_status,case when is_super_admin()then now()else null end,case when is_super_admin()then now()+make_interval(mins=>(p_input->>'durationMinutes')::integer)else null end,(p_input->>'durationMinutes')::integer)returning id into v_id;perform platform_audit('support.session_requested',(p_input->>'organizationId')::uuid,nullif(p_input->>'workspaceId','')::uuid,'Support access requested; no impersonation');return v_id;end$$;
create or replace function public.approve_support_session(p_session_id uuid,p_expected_version integer)returns void language plpgsql security definer set search_path=public as $$declare s support_sessions%rowtype;begin if not is_super_admin()then raise exception'super admin approval required';end if;select*into s from support_sessions where id=p_session_id for update;if not found or s.status<>'pending'or s.version<>p_expected_version then raise exception'invalid or stale support request';end if;update support_sessions set status='active',approved_by=auth.uid(),approved_at=now(),expires_at=now()+make_interval(mins=>duration_minutes),version=version+1 where id=s.id;perform platform_audit('support.session_approved',s.organization_id,s.workspace_id,'Read-only support session approved');end$$;
create or replace function public.end_support_session(p_session_id uuid,p_expected_version integer)returns void language plpgsql security definer set search_path=public as $$declare s support_sessions%rowtype;begin if not is_platform_staff()then raise exception'platform staff required';end if;select*into s from support_sessions where id=p_session_id for update;if not found or s.version<>p_expected_version or(s.requested_by<>auth.uid()and not is_super_admin())then raise exception'invalid support session';end if;update support_sessions set status='ended',ended_at=now(),version=version+1 where id=s.id;perform platform_audit('support.session_ended',s.organization_id,s.workspace_id,'Support session ended');end$$;
create or replace function public.create_platform_feature_flag(p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if not is_super_admin()then raise exception'super admin required';end if;insert into feature_flags(key,name,description,rollout_percentage,created_by,updated_by)values(p_input->>'key',p_input->>'name',p_input->>'description',(p_input->>'rolloutPercentage')::integer,auth.uid(),auth.uid())returning id into v_id;return v_id;end$$;create or replace function public.assign_platform_feature_flag(p_input jsonb)returns void language plpgsql security definer set search_path=public as $$begin if not is_super_admin()then raise exception'super admin required';end if;insert into feature_flag_assignments(flag_id,assignment_type,assignment_value,enabled,created_by)values((p_input->>'flagId')::uuid,p_input->>'assignmentType',p_input->>'assignmentValue',(p_input->>'enabled')::boolean,auth.uid())on conflict(flag_id,assignment_type,assignment_value)do update set enabled=excluded.enabled,updated_at=now(),version=feature_flag_assignments.version+1;end$$;
create or replace function public.publish_platform_release(p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if not is_super_admin()then raise exception'super admin required';end if;insert into release_registry(version_name,deployment_environment,status,notes,approval_status,approved_by,published_at,created_by)values(p_input->>'versionName',p_input->>'deploymentEnvironment','published',nullif(p_input->>'notes',''),'approved',auth.uid(),now(),auth.uid())returning id into v_id;return v_id;end$$;create or replace function public.archive_platform_release(p_release_id uuid,p_expected_version integer)returns void language plpgsql security definer set search_path=public as $$begin if not is_super_admin()then raise exception'super admin required';end if;update release_registry set status='archived',deleted_at=now(),updated_at=now(),version=version+1 where id=p_release_id and version=p_expected_version and deleted_at is null;if not found then raise exception'release stale or missing';end if;end$$;
create or replace function public.add_customer_health_note(p_input jsonb)returns void language plpgsql security definer set search_path=public as $$begin if not is_platform_staff()then raise exception'platform staff required';end if;insert into customer_success_notes(organization_id,author_id,body)values((p_input->>'organizationId')::uuid,auth.uid(),p_input->>'note');perform platform_audit('customer_success.note_added',(p_input->>'organizationId')::uuid,null,'Customer success note added');end$$;
revoke all on function public.platform_customer_directory(),public.platform_audit(text,uuid,uuid,text),public.request_support_session(jsonb),public.approve_support_session(uuid,integer),public.end_support_session(uuid,integer),public.create_platform_feature_flag(jsonb),public.assign_platform_feature_flag(jsonb),public.publish_platform_release(jsonb),public.archive_platform_release(uuid,integer),public.add_customer_health_note(jsonb)from public;grant execute on function public.platform_customer_directory(),public.request_support_session(jsonb),public.approve_support_session(uuid,integer),public.end_support_session(uuid,integer),public.create_platform_feature_flag(jsonb),public.assign_platform_feature_flag(jsonb),public.publish_platform_release(jsonb),public.archive_platform_release(uuid,integer),public.add_customer_health_note(jsonb)to authenticated;
